    Document doc = new Document();
    final int base = Integer.MAX_VALUE;
    addPointToDoc(
        FIELD_NAME,
        doc,
        GeoEncodingUtils.decodeLatitude(base - 2),
        GeoEncodingUtils.decodeLongitude(base - 2));
    w.addDocument(doc);
    w.flush();

