  /** A predicate that checks whether a given point is within a component2D geometry. */
  public static class Component2DPredicate extends Grid {

    private final Component2D tree;

    private Component2DPredicate(
        int latShift,
        int lonShift,
        int latBase,
        int lonBase,
        int maxLatDelta,
        int maxLonDelta,
        byte[] relations,
        Component2D tree) {
      super(latShift, lonShift, latBase, lonBase, maxLatDelta, maxLonDelta, relations);
      this.tree = tree;
    }

    /**
     * Check whether the given point is within the considered polygon. NOTE: this operates directly
     * on the encoded representation of points.
     */
    public boolean test(int lat, int lon) {
      final int lat2 = ((lat - Integer.MIN_VALUE) >>> latShift);
      if (lat2 < latBase || lat2 >= latBase + maxLatDelta) {
        return false;
      }
      int lon2 = ((lon - Integer.MIN_VALUE) >>> lonShift);
      if (lon2 < lonBase) { // wrap
        final int wrapDelta = 1 << (32 - lonShift);
        lon2 += wrapDelta;
      }
      assert Integer.toUnsignedLong(lon2) >= lonBase;
      assert lon2 - lonBase >= 0;
      if (lon2 - lonBase >= maxLonDelta) {
        return false;
      }

      final int latOffset = lat2 - latBase;
      final int lonOffset = lon2 - lonBase;
      final int cellIndex = latOffset * maxLonDelta + lonOffset;
      final int insideRelation = Relation.CELL_INSIDE_QUERY.ordinal();
      final int crossesRelation = Relation.CELL_CROSSES_QUERY.ordinal();
      final int relation = relations[cellIndex];
      if (relation == crossesRelation) {
        final int encodedLat = lat;
        final int encodedLon = lon;
        final double latDecode = LAT_DECODE;
        final double lonDecode = LON_DECODE;
        final double decodedLat = encodedLat * latDecode;
        final double decodedLon = encodedLon * lonDecode;
        final double minX = tree.getMinX();
        final double maxX = tree.getMaxX();
        final double minY = tree.getMinY();
        final double maxY = tree.getMaxY();
        final double west = minX;
        final double east = maxX;
        final double south = minY;
        final double north = maxY;
        final boolean westOk = decodedLon >= west;
        final boolean eastOk = decodedLon <= east;
        final boolean southOk = decodedLat >= south;
        final boolean northOk = decodedLat <= north;

        if (tree instanceof Polygon2D) {
          final Polygon2D polygon = (Polygon2D) tree;
          if (westOk) {
            if (eastOk) {
              if (southOk) {
                if (northOk) {
                  final double pointX = decodedLon;
                  final double pointY = decodedLat;
                  final EdgeTree edges = polygon.tree;
                  final boolean insideShape = edges.contains(pointX, pointY);
